// Coverage area of the MVP: the state of Paraná. The engine answers 422 (`fora_da_regiao`)
// outside it, so the property screens block locations outside PR before reaching the API.
// Data generated by motor_field_shift/scripts/export_parana_frontend.py.
import parana from "./parana.json";

type Ring = number[][]; // [lon, lat]

const boundary = parana.boundary as Ring[];
export const municipalities = (parana.municipalities as [string, number, number][]).map(
  ([name, lat, lon]) => ({ name, label: `${name}, PR`, lat, lon }),
);

function normalize(s: string) {
  return s.normalize("NFD").replace(/[̀-ͯ]/g, "").toLowerCase().replace(/\s+/g, " ").trim();
}

const byName = new Map(municipalities.map((m) => [normalize(m.name), m]));

/** Paraná municipality for a "City" or "City, PR" / "City / PR" text, or undefined. */
export function findMunicipality(text: string) {
  const m = normalize(text).match(/^(.*?)(?:\s*[,/-]\s*(pr|parana))?$/);
  return m ? byName.get(m[1]) : undefined;
}

function insideRing(lon: number, lat: number, ring: Ring) {
  let inside = false;
  for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
    const [xi, yi] = ring[i], [xj, yj] = ring[j];
    if (yi > lat !== yj > lat && lon < ((xj - xi) * (lat - yi)) / (yj - yi) + xi) inside = !inside;
  }
  return inside;
}

/** True when the point falls inside Paraná (boundary buffered ~1 km; the engine does the exact check). */
export function insideParana(lat: number, lon: number) {
  return Number.isFinite(lat) && Number.isFinite(lon) && boundary.some((ring) => insideRing(lon, lat, ring));
}

/** True when the latitude/longitude texts form a valid point inside Paraná. */
export function coordinatesInParana(latitude: string, longitude: string) {
  if (!latitude.trim() || !longitude.trim()) return false;
  return insideParana(Number(latitude), Number(longitude));
}
